<script lang="ts">import {brand} from '$config/brand';const q=encodeURIComponent(brand.address);const mapEmbedUrl=`https://maps.google.com/maps?q=${q}&z=16&hl=en&output=embed`;const directionsUrl=`https://www.google.com/maps/search/?api=1&query=${q}`;</script><div class="dn-showroom-map"><iframe class="dn-showroom-map__frame" src={mapEmbedUrl} title={`Map to ${brand.name}`} loading="lazy"></iframe><a class="dn-showroom-map__link" href={directionsUrl} target="_blank" rel="noreferrer">Open in Google Maps</a></div><style>.dn-showroom-map{position:relative;min-height:420px;overflow:hidden;border-radius:24px;background:#e9ebee}.dn-showroom-map__frame{display:block;width:100%;height:420px;border:0}.dn-showroom-map__link{position:absolute;right:16px;bottom:16px;padding:12px 18px;border-radius:999px;background:#fff;color:#111;font-weight:700}@media(max-width:767px){.dn-showroom-map,.dn-showroom-map__frame{min-height:300px;height:300px}}</style>
